/* fp_to_json.c -- convert canonical ABI fingerprint records into JSON.
 *
 * Input (stdin): lines of `SECTION<TAB>key<TAB>value`.  Blank lines and lines
 * beginning with '#' are ignored.  Output (stdout) is a JSON object grouping
 * records by section:
 *
 *   {"format":"abi_fp_1","sections":{"V":{...},"L":{...},...}}
 *
 * This exists so the JSON artifact is generated by C (no Python and no
 * fragile shell escaping).  The canonical text fingerprint is the
 * authoritative artifact that run.sh diffs; JSON is a derived convenience.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *sec;
    char *key;
    char *val;
} Record;

static Record *g_recs;
static size_t g_count;
static size_t g_cap;

static char *xstrdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char *p = (char *)malloc(n);
    if (!p) {
        fputs("fp_to_json: out of memory\n", stderr);
        exit(2);
    }
    memcpy(p, s, n);
    return p;
}

static void *xmalloc(size_t n)
{
    void *p = malloc(n ? n : 1);
    if (!p) {
        fputs("fp_to_json: out of memory\n", stderr);
        exit(2);
    }
    return p;
}

/* Skip duplicate section+key (keep first) so JSON keys stay unique. */
static void add_record(const char *sec, const char *key, const char *val)
{
    size_t i;
    for (i = 0; i < g_count; ++i) {
        if (strcmp(g_recs[i].sec, sec) == 0 && strcmp(g_recs[i].key, key) == 0)
            return;
    }
    if (g_count == g_cap) {
        g_cap = g_cap ? g_cap * 2 : 256;
        g_recs = (Record *)realloc(g_recs, g_cap * sizeof(Record));
        if (!g_recs) {
            fputs("fp_to_json: out of memory\n", stderr);
            exit(2);
        }
    }
    g_recs[g_count].sec = xstrdup(sec);
    g_recs[g_count].key = xstrdup(key);
    g_recs[g_count].val = xstrdup(val);
    ++g_count;
}

static void json_string(const char *s)
{
    const unsigned char *p = (const unsigned char *)s;
    putchar('"');
    for (; *p; ++p) {
        switch (*p) {
        case '"':  fputs("\\\"", stdout); break;
        case '\\': fputs("\\\\", stdout); break;
        case '\b': fputs("\\b", stdout);  break;
        case '\f': fputs("\\f", stdout);  break;
        case '\n': fputs("\\n", stdout);  break;
        case '\r': fputs("\\r", stdout);  break;
        case '\t': fputs("\\t", stdout);  break;
        default:
            if (*p < 0x20)
                printf("\\u%04x", (unsigned)*p);
            else
                putchar((int)*p);
        }
    }
    putchar('"');
}

int main(void)
{
    char line[8192];
    const char *format = "abi_fp_1";
    char **secs;
    size_t nsec = 0, i, j;

    while (fgets(line, sizeof(line), stdin)) {
        char *sec, *key, *val, *tab, *nl;
        size_t len = strlen(line);

        while (len && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';
        if (len == 0 || line[0] == '#')
            continue;

        sec = line;
        tab = strchr(sec, '\t');
        if (!tab) continue;
        *tab = '\0';
        key = tab + 1;
        tab = strchr(key, '\t');
        if (!tab) continue;
        *tab = '\0';
        val = tab + 1;
        nl = strchr(val, '\t');
        if (nl) *nl = '\0';

        add_record(sec, key, val);
    }

    /* Discover distinct sections in first-appearance order. */
    secs = (char **)xmalloc(g_count * sizeof(char *));
    for (i = 0; i < g_count; ++i) {
        int seen = 0;
        for (j = 0; j < nsec; ++j) {
            if (strcmp(secs[j], g_recs[i].sec) == 0) { seen = 1; break; }
        }
        if (!seen) secs[nsec++] = g_recs[i].sec;
    }

    fputs("{\"format\":", stdout);
    json_string(format);
    fputs(",\"sections\":{", stdout);

    for (i = 0; i < nsec; ++i) {
        int first_key = 1;
        if (i) putchar(',');
        json_string(secs[i]);
        fputs(":{", stdout);
        for (j = 0; j < g_count; ++j) {
            if (strcmp(g_recs[j].sec, secs[i]) != 0) continue;
            if (!first_key) putchar(',');
            first_key = 0;
            json_string(g_recs[j].key);
            putchar(':');
            json_string(g_recs[j].val);
        }
        fputc('}', stdout);
    }

    fputs("}}\n", stdout);
    free(secs);
    return 0;
}
